import{_ as a,W as p,s as l,u as d,I as i,ah as r,w as t,Z as e,A as n}from"./chunks/framework.DRqsSc0o.js";import"./chunks/theme.DlTh90wK.js";const v=JSON.parse('{"title":"如何在 Linux 中挂载 Bitlocker 加密的 Windows 分区 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中挂载 Bitlocker 加密的 Windows 分区 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中挂载 Bitlocker 加密的 Windows 分区 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中挂载 Bitlocker 加密的 Windows 分区 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211111 How to Mount Bitlocker Encrypted Windows Partition in Linux","title":"如何在 Linux 中挂载 Bitlocker 加密的 Windows 分区","tag":"202111"},"relativePath":"202111/20211111 How to Mount Bitlocker Encrypted Windows Partition in Linux.md","filePath":"[post].md"}'),u={name:"202111/20211111 How to Mount Bitlocker Encrypted Windows Partition in Linux.md"};function c(m,s,g,k,w,h){const o=p("Link");return d(),l("div",null,[s[22]||(s[22]=i("h1",{id:"如何在-linux-中挂载-bitlocker-加密的-windows-分区",tabindex:"-1"},[t("如何在 Linux 中挂载 Bitlocker 加密的 Windows 分区 "),i("a",{class:"header-anchor",href:"#如何在-linux-中挂载-bitlocker-加密的-windows-分区","aria-label":"Permalink to 如何在 Linux 中挂载 Bitlocker 加密的 Windows 分区"},"​")],-1)),i("blockquote",null,[i("p",null,[s[1]||(s[1]=t("情况是这样的。我的系统自带 Windows 10 Pro，并且带有 BitLocker 加密功能。我 ")),e(o,{href:"https://itsfoss.com/dual-boot-ubuntu-windows-bitlocker/"},{default:n(()=>s[0]||(s[0]=[t("甚至在 Windows 启用了 BitLocker 加密的情况下，以双启动模式安装了 Ubuntu")])),_:1}),s[2]||(s[2]=t("。"))])]),s[23]||(s[23]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202111/22/144133k6n9xsnnt46t0z94.jpg",alt:""})],-1)),s[24]||(s[24]=i("p",null,[t("你可以轻松地从 Linux 中访问 Windows 文件。没有什么高科技的东西。只要进入文件管理器，点击通常位于“"),i("ruby",null,[t("其他位置"),i("rt",null,"Other Locations")]),t("”标签下的 Windows 分区。")],-1)),s[25]||(s[25]=i("p",null,[i("img",{src:"https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/mount-encrypted-windows-partition-in-linux.png?resize=800%2C476&ssl=1",alt:"Mounting Windows partition through the file manager in Linux desktop"})],-1)),s[26]||(s[26]=i("p",null,"对于 BitLocker 加密的 Windows 分区来说，这个过程也不是太复杂。只是当你试图挂载 Windows 分区时，它会要求你输入密码。",-1)),s[27]||(s[27]=i("p",null,[i("img",{src:"https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/password-needed-for-encrypted-windows-drive-mount-in-Linux.png?resize=788%2C380&ssl=1",alt:"Password required for encrypted Windows drive mount in Linux"})],-1)),s[28]||(s[28]=i("p",null,"这是能工作的。在我的情况中，我输入了 48 位 BitLocker 恢复密码，它解密了 Windows 分区，并在带有 GNOME 40 的 Ubuntu 21.10 中毫无问题地挂载了它。",-1)),s[29]||(s[29]=i("p",null,"试试你的 BitLocker 密码。如果这不起作用，试试恢复密码。对于普通的 Windows 10 Pro 用户，恢复密码存储在你的微软账户中。",-1)),i("p",null,[e(o,{href:"https://account.microsoft.com/devices/recoverykey?refd=support.microsoft.com"},{default:n(()=>s[3]||(s[3]=[t("BitLocker Recovery Password in Micrsoft Account")])),_:1})]),s[30]||(s[30]=i("p",null,[t("输入恢复密码，你会看到 Windows 分区和它的文件现在可以访问。勾选“"),i("ruby",null,[t("记住密码"),i("rt",null,"Remember Password")]),t("”框也是为了进一步使用而节省时间。")],-1)),s[31]||(s[31]=i("p",null,[i("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/encrypted-windows-partition-mounted-in-Linux.png?resize=800%2C491&ssl=1",alt:"Encrypted Windows partition now mounted in Linux"})],-1)),s[32]||(s[32]=i("p",null,"如果上述方法对你不起作用，或者你不熟悉命令行，还有一个替代方法。",-1)),i("p",null,[s[5]||(s[5]=t("这个方法包括使用一个叫做 ")),e(o,{href:"https://github.com/Aorimn/dislocker"},{default:n(()=>s[4]||(s[4]=[t("Dislocker")])),_:1}),s[6]||(s[6]=t(" 的工具。"))]),s[33]||(s[33]=r(`<h3 id="使用-dislocker-在-linux-中挂载-botlocker-加密的-windows-分区-命令行方法" tabindex="-1">使用 Dislocker 在 Linux 中挂载 BotLocker 加密的 Windows 分区（命令行方法） <a class="header-anchor" href="#使用-dislocker-在-linux-中挂载-botlocker-加密的-windows-分区-命令行方法" aria-label="Permalink to 使用 Dislocker 在 Linux 中挂载 BotLocker 加密的 Windows 分区（命令行方法）">​</a></h3><p>使用 Dislocker 分为两部分。第一部分是解开 BitLocker 的加密，并给出一个名为 <code>dislocker-file</code> 的文件。这基本上是一个虚拟的 NTFS 分区。第二部分是挂载你刚刚得到的虚拟 NTFS 分区。</p><p>你需要 BitLocker 密码或恢复密码来解密加密的驱动器。</p><p>让我们来看看详细的步骤。</p><h4 id="步骤-1-安装-disclocker" tabindex="-1">步骤 1：安装 Disclocker <a class="header-anchor" href="#步骤-1-安装-disclocker" aria-label="Permalink to 步骤 1：安装 Disclocker">​</a></h4><p>大多数 Linux 发行版的仓库中都有 Dislocker。请使用你的发行版的包管理器来安装它。</p><p>在基于 Ubuntu 和 Debian 的发行版上，使用这个命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install dislocker</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/11/install-dislocker-ubuntu.png?resize=786%2C386&amp;ssl=1" alt="Installing Dislocker in Ubuntu"></p><h4 id="步骤-2-创建挂载点" tabindex="-1">步骤 2：创建挂载点 <a class="header-anchor" href="#步骤-2-创建挂载点" aria-label="Permalink to 步骤 2：创建挂载点">​</a></h4><p>你需要创建两个挂载点。一个是 Dislocker 生成 <code>dislocker-file</code> 的地方，另一个是将这个 <code>dislocker-file</code>（虚拟文件系统）作为一个回环设备挂载。</p><p>没有命名限制，你可以给这些挂载目录起任何你想要的名字。</p><p>逐一使用这些命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mkdir -p /media/decrypt</span></span>
<span class="line"><span>sudo mkdir -p /media/windows-mount</span></span></code></pre></div><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/creating-mount-points-for-dislocker.png?resize=777%2C367&amp;ssl=1" alt="Creating mount points for dislocker"></p><h4 id="步骤-3-获取需要解密的分区信息" tabindex="-1">步骤 3：获取需要解密的分区信息 <a class="header-anchor" href="#步骤-3-获取需要解密的分区信息" aria-label="Permalink to 步骤 3：获取需要解密的分区信息">​</a></h4><p>你需要 Windows 分区的名称。你可以使用文件资源管理器或像 Gparted 这样的 GUI 工具。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/show-device-name-gparted.png?resize=800%2C416&amp;ssl=1" alt="Get the partition name"></p><p>在我的例子中，Windows 分区是 <code>/dev/nvme0n1p3</code>。对你的系统来说，这将是不同的。你也可以使用命令行来达到这个目的。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo lsblk</span></span></code></pre></div><h4 id="步骤-4-解密分区并挂载" tabindex="-1">步骤 4：解密分区并挂载 <a class="header-anchor" href="#步骤-4-解密分区并挂载" aria-label="Permalink to 步骤 4：解密分区并挂载">​</a></h4><p>你已经设置好了一切。现在是真正的部分。</p><p><strong>如果你有 BitLocker 密码</strong>，以这种方式使用 <code>dislocker</code> 命令（用实际值替换 <code>&lt;partition_name&gt;</code> 和 <code>&lt;password&gt;</code>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo dislocker &lt;partition_name&gt; -u&lt;password&gt; -- /media/decrypt</span></span></code></pre></div><p>如果你只有恢复密码，请以这种方式使用该命令用实际值替换 <code>&lt;partition_name&gt;</code> 和 <code>&lt;password&gt;</code>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo dislocker &lt;partition_name&gt; -p&lt;recovery_password&gt; -- /media/decrypt</span></span></code></pre></div><p>在解密该分区时，应该不会花很长时间。你应该在指定的挂载点看到 <code>dislocker-file</code>，在我们的例子中是 <code>/media/decrypt</code>。现在挂载这个 dislocker-file：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mount -o loop /media/decrypt/dislocker-file /media/windows-mount</span></span></code></pre></div><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/mount-dislocker-decrypted-windows-partition.png?resize=777%2C253&amp;ssl=1" alt=""></p><p>完成了。你的 BitLocker 加密的 Windows 分区已经被解密并挂载到 Linux 中。你也可以从文件资源管理器中访问它。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/discloker-mount-encrypted-windows-partition.png?resize=800%2C483&amp;ssl=1" alt="Mounting Dislocker decrypted Windows partition with file manager"></p><h4 id="文件系统类型错误的故障排除提示" tabindex="-1">文件系统类型错误的故障排除提示 <a class="header-anchor" href="#文件系统类型错误的故障排除提示" aria-label="Permalink to 文件系统类型错误的故障排除提示">​</a></h4><p>如果你遇到这样的错误：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mount: /media/windows-mount: wrong fs type, bad option, bad superblock on /dev/loop35, missing codepage or helper program, or other error.</span></span></code></pre></div><p>你应该在挂载时指定文件系统。</p><p>对于NTFS，使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mount -t ntfs-3g -o loop /media/decrypt/dislocker-file /media/windows-mount</span></span></code></pre></div><p>对于 exFAT，使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mount -t exFAT-fuse -o loop /media/decrypt/dislocker-file /media/windows-mount</span></span></code></pre></div><h4 id="解除对-windows-分区的挂载" tabindex="-1">解除对 Windows 分区的挂载 <a class="header-anchor" href="#解除对-windows-分区的挂载" aria-label="Permalink to 解除对 Windows 分区的挂载">​</a></h4><p>你可以从文件管理器中取消挂载的分区。只要<strong>点击名为 windows-mount 的分区旁边的卸载符号</strong>。</p><p>或者，你可以使用卸载命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo umount /media/decrypt</span></span>
<span class="line"><span>sudo umount /media/windows-mount</span></span></code></pre></div><p>我希望这对你有帮助。如果你还有问题或建议，请在评论中告诉我。</p><hr>`,45)),i("p",null,[s[8]||(s[8]=t("via: ")),e(o,{href:"https://itsfoss.com/mount-encrypted-windows-partition-linux/"},{default:n(()=>s[7]||(s[7]=[t("https://itsfoss.com/mount-encrypted-windows-partition-linux/")])),_:1})]),i("p",null,[s[13]||(s[13]=t("作者：")),e(o,{href:"https://itsfoss.com/author/abhishek/"},{default:n(()=>s[9]||(s[9]=[t("Abhishek Prakash")])),_:1}),s[14]||(s[14]=t(" 选题：")),e(o,{href:"https://github.com/lujun9972"},{default:n(()=>s[10]||(s[10]=[t("lujun9972")])),_:1}),s[15]||(s[15]=t(" 译者：")),e(o,{href:"https://github.com/geekpi"},{default:n(()=>s[11]||(s[11]=[t("geekpi")])),_:1}),s[16]||(s[16]=t(" 校对：")),e(o,{href:"https://github.com/wxy"},{default:n(()=>s[12]||(s[12]=[t("wxy")])),_:1})]),i("p",null,[s[19]||(s[19]=t("本文由 ")),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>s[17]||(s[17]=[t("LCTT")])),_:1}),s[20]||(s[20]=t(" 原创编译，")),e(o,{href:"https://linux.cn/"},{default:n(()=>s[18]||(s[18]=[t("Linux中国")])),_:1}),s[21]||(s[21]=t(" 荣誉推出"))])])}const x=a(u,[["render",c]]);export{v as __pageData,x as default};
